export const ordersRouter = Router();

ordersRouter.get('/orders', requireUser, async (req, res) => {
  return res.json(await listOrders(req.user.id));
});

ordersRouter.delete('/orders/:id', requireUser, async (req, res) => {
  await cancelOrder({ id: req.params.id, userId: req.user.id });
  return res.sendStatus(204);
});
